function formatTimestamp(dateObj){var year=dateObj.getFullYear();var month=(dateObj.getMonth()+1).toString().padStart(2,'0');var day=dateObj.getDate().toString().padStart(2,'0');var hours=dateObj.getHours().toString().padStart(2,'0');var minutes=dateObj.getMinutes().toString().padStart(2,'0');var seconds=dateObj.getSeconds().toString().padStart(2,'0');return year+'-'+month+'-'+day+' '+hours+':'+minutes+':'+seconds;}function calculateExecutionDuration(startTime,endTime){return(endTime-startTime).toFixed(2)+' ms';}function logEvent(message,level){var lvl=level||'INFO';var time=formatTimestamp(new Date());console.log('['+time+']['+lvl+']'+message);}window.Utils={formatTimestamp:formatTimestamp,calculateExecutionDuration:calculateExecutionDuration,logEvent:logEvent};function registerServiceWorker(){if('serviceWorker' in navigator){navigator.serviceWorker.register('sw.js').catch(function(err){});}}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',registerServiceWorker);}else{registerServiceWorker();}